"""BMAD Bridge — Bidirectional sync between _bmad-output/ artifacts and vault.

Implements artifact sync, lifecycle management, listing, status queries,
and linking for BMAD workflow artifacts (PRD, Architecture, Epic, Story).
"""

import hashlib
import json
import logging
from datetime import datetime, timezone
from pathlib import Path

import yaml

logger = logging.getLogger(__name__)

# ── Artifact Type Definitions ─────────────────────────────────────────

ARTIFACT_TYPES = {"prd", "architecture", "epic", "story"}

FILENAME_TYPE_MAP = {
    "prd-": "prd",
    "architecture-": "architecture",
    "epic-": "epic",
    "story-": "story",
}

LIFECYCLE_TRANSITIONS: dict[str, dict[str, list[str]]] = {
    "prd": {
        "draft": ["in_review"],
        "in_review": ["draft", "approved"],
        "approved": ["archived"],
        "archived": [],
    },
    "architecture": {
        "proposed": ["accepted"],
        "accepted": ["proposed", "deprecated"],
        "deprecated": ["superseded"],
        "superseded": [],
    },
    "epic": {
        "defined": ["in_progress"],
        "in_progress": ["defined", "completed"],
        "completed": ["retrospected"],
        "retrospected": [],
    },
    "story": {
        "draft": ["ready"],
        "ready": ["draft", "in_progress"],
        "in_progress": ["ready", "implemented"],
        "implemented": ["in_progress", "verified"],
        "verified": [],
    },
}

DEFAULT_STATUS: dict[str, str] = {
    "prd": "draft",
    "architecture": "proposed",
    "epic": "defined",
    "story": "draft",
}

RELATIONSHIP_TYPES = {"depends_on", "implements", "informs", "supersedes"}

TIER1_REQUIRED = {
    "bmad_artifact_type",
    "bmad_project",
    "bmad_status",
    "bmad_source",
    "bmad_synced_at",
    "bmad_content_hash",
}


# ── Schema Validation ─────────────────────────────────────────────────


def validate_frontmatter(data: dict, artifact_type: str) -> list[str]:
    """Validate frontmatter against the 3-tier schema. Returns list of errors."""
    errors: list[str] = []

    if artifact_type not in ARTIFACT_TYPES:
        errors.append(f"Unknown artifact_type: {artifact_type}")
        return errors

    for field in TIER1_REQUIRED:
        if field not in data:
            errors.append(f"Missing required field: {field}")

    if data.get("bmad_artifact_type") != artifact_type:
        errors.append(
            f"bmad_artifact_type mismatch: expected '{artifact_type}', "
            f"got '{data.get('bmad_artifact_type')}'"
        )

    status = data.get("bmad_status", "")
    valid_statuses = LIFECYCLE_TRANSITIONS.get(artifact_type, {})
    if status and status not in valid_statuses:
        errors.append(
            f"Invalid status '{status}' for {artifact_type}. "
            f"Valid: {list(valid_statuses.keys())}"
        )

    links = data.get("bmad_linked_artifacts", [])
    if links:
        for i, link in enumerate(links):
            if not isinstance(link, dict):
                errors.append(f"Link {i}: must be a dict, got {type(link).__name__}")
                continue
            if "target" not in link:
                errors.append(f"Link {i}: missing 'target'")
            if link.get("relationship") and link["relationship"] not in RELATIONSHIP_TYPES:
                errors.append(
                    f"Link {i}: invalid relationship '{link['relationship']}'. "
                    f"Valid: {RELATIONSHIP_TYPES}"
                )

    return errors


# ── Helpers ───────────────────────────────────────────────────────────


def _detect_artifact_type(path: Path, frontmatter: dict) -> str | None:
    """Detect artifact type from frontmatter or filename pattern."""
    if fm_type := frontmatter.get("bmad_artifact_type"):
        if fm_type in ARTIFACT_TYPES:
            return fm_type

    stem = path.stem.lower()
    for prefix, atype in FILENAME_TYPE_MAP.items():
        if stem.startswith(prefix):
            return atype
    return None


def _parse_frontmatter(content: str) -> tuple[dict, str]:
    """Parse YAML frontmatter from markdown content."""
    if not content.startswith("---"):
        return {}, content

    parts = content.split("---", 2)
    if len(parts) < 3:
        return {}, content

    try:
        fm = yaml.safe_load(parts[1]) or {}
    except yaml.YAMLError:
        fm = {}

    return fm, "---".join(["", parts[1], parts[2]])


def _compute_hash(content: str) -> str:
    return f"sha256:{hashlib.sha256(content.encode()).hexdigest()[:16]}"


def _now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def _derive_project(path: Path, frontmatter: dict) -> str:
    """Derive project name from frontmatter or filename."""
    if proj := frontmatter.get("bmad_project"):
        return proj
    if proj := frontmatter.get("project_name"):
        return proj
    stem = path.stem
    for prefix in FILENAME_TYPE_MAP:
        if stem.startswith(prefix):
            return stem[len(prefix):]
    return stem


# ── BMAD Bridge Operations ────────────────────────────────────────────


class BmadBridge:
    """Manages BMAD artifact sync between _bmad-output/ and the vault."""

    VAULT_PREFIX = "projects"

    def __init__(self, vault_path: str | Path, bmad_output_path: str | Path):
        self.vault_path = Path(vault_path)
        self.bmad_output = Path(bmad_output_path)

    def _vault_artifact_dir(self, project: str) -> Path:
        return self.vault_path / self.VAULT_PREFIX / project

    def _read_vault_artifact(self, project: str, name: str) -> tuple[dict, str] | None:
        path = self._vault_artifact_dir(project) / f"{name}.md"
        if not path.exists():
            return None
        return _parse_frontmatter(path.read_text(encoding="utf-8"))

    def _write_vault_artifact(self, project: str, name: str, fm: dict, body: str) -> Path:
        dest_dir = self._vault_artifact_dir(project)
        dest_dir.mkdir(parents=True, exist_ok=True)
        dest = dest_dir / f"{name}.md"

        yaml_str = yaml.dump(fm, default_flow_style=False, sort_keys=False, allow_unicode=True)
        dest.write_text(f"---\n{yaml_str}---\n{body}", encoding="utf-8")
        return dest

    # ── Sync ──────────────────────────────────────────────────────────

    def sync_artifact(self, source_path: str) -> dict:
        """Sync a single BMAD artifact from _bmad-output/ to vault."""
        src = Path(source_path)
        if not src.is_absolute():
            src = self.bmad_output / src

        if not src.exists():
            return {"error": f"Source not found: {src}"}

        content = src.read_text(encoding="utf-8")
        source_fm, body = _parse_frontmatter(content)

        artifact_type = _detect_artifact_type(src, source_fm)
        if not artifact_type:
            return {"error": f"Cannot detect artifact type for: {src.name}"}

        project = _derive_project(src, source_fm)
        name = src.stem

        # Build enriched frontmatter (Tier 1 + preserve existing Tier 2/3)
        existing = self._read_vault_artifact(project, name)
        existing_fm = existing[0] if existing else {}

        enriched: dict = {
            "bmad_artifact_type": artifact_type,
            "bmad_project": project,
            "bmad_status": existing_fm.get("bmad_status", DEFAULT_STATUS[artifact_type]),
            "bmad_source": str(src.relative_to(src.parents[2]) if len(src.parents) > 2 else src.name),
            "bmad_synced_at": _now_iso(),
            "bmad_content_hash": _compute_hash(content),
            "tags": list({*source_fm.get("tags", []), "bmad", project}),
        }

        # Preserve Tier 2 (links, history)
        if links := existing_fm.get("bmad_linked_artifacts"):
            enriched["bmad_linked_artifacts"] = links
        if history := existing_fm.get("bmad_status_history"):
            enriched["bmad_status_history"] = history

        # Copy Tier 3 type-specific fields from source
        for key, val in source_fm.items():
            if key.startswith("bmad_") and key not in enriched:
                enriched[key] = val

        errors = validate_frontmatter(enriched, artifact_type)
        if errors:
            return {"error": f"Validation failed: {'; '.join(errors)}"}

        dest = self._write_vault_artifact(project, name, enriched, body)
        logger.info(f"Synced {name} ({artifact_type}) to {dest}")
        return {"synced": name, "type": artifact_type, "project": project, "path": str(dest)}

    def sync_glob(self, pattern: str) -> dict:
        """Sync all matching artifacts from _bmad-output/."""
        matches = list(self.bmad_output.glob(pattern))
        results = []
        errors = []
        for src in matches:
            if src.is_file() and src.suffix == ".md":
                result = self.sync_artifact(str(src))
                if "error" in result:
                    errors.append(result)
                else:
                    results.append(result)
        return {"synced": len(results), "errors": len(errors), "details": results + errors}

    # ── Query ─────────────────────────────────────────────────────────

    def list_artifacts(
        self,
        artifact_type: str | None = None,
        status: str | None = None,
        project: str | None = None,
    ) -> list[dict]:
        """List tracked BMAD artifacts with optional filters."""
        projects_dir = self.vault_path / self.VAULT_PREFIX
        if not projects_dir.exists():
            return []

        artifacts = []
        search_dirs = (
            [projects_dir / project] if project else list(projects_dir.iterdir())
        )

        for proj_dir in search_dirs:
            if not proj_dir.is_dir():
                continue
            for md_file in proj_dir.glob("*.md"):
                fm, _ = _parse_frontmatter(md_file.read_text(encoding="utf-8"))
                if "bmad_artifact_type" not in fm:
                    continue
                if artifact_type and fm.get("bmad_artifact_type") != artifact_type:
                    continue
                if status and fm.get("bmad_status") != status:
                    continue

                artifacts.append({
                    "name": md_file.stem,
                    "type": fm.get("bmad_artifact_type"),
                    "status": fm.get("bmad_status"),
                    "project": fm.get("bmad_project"),
                    "synced_at": fm.get("bmad_synced_at"),
                })

        return artifacts

    def get_artifact_status(self, name: str, project: str | None = None) -> dict:
        """Get full detail for a single artifact."""
        projects_dir = self.vault_path / self.VAULT_PREFIX
        search_dirs = (
            [projects_dir / project] if project else list(projects_dir.iterdir())
        )

        for proj_dir in search_dirs:
            if not proj_dir.is_dir():
                continue
            path = proj_dir / f"{name}.md"
            if path.exists():
                fm, _ = _parse_frontmatter(path.read_text(encoding="utf-8"))
                return {
                    "name": name,
                    "found": True,
                    **fm,
                }

        return {"name": name, "found": False}

    # ── Lifecycle ─────────────────────────────────────────────────────

    def update_status(self, name: str, new_status: str, project: str | None = None) -> dict:
        """Update artifact lifecycle status with transition validation."""
        status_info = self.get_artifact_status(name, project)
        if not status_info.get("found"):
            return {"error": f"Artifact not found: {name}"}

        artifact_type = status_info.get("bmad_artifact_type")
        current_status = status_info.get("bmad_status")
        transitions = LIFECYCLE_TRANSITIONS.get(artifact_type, {})
        valid_next = transitions.get(current_status, [])

        if new_status not in valid_next:
            return {
                "error": (
                    f"Cannot transition {artifact_type} from '{current_status}' "
                    f"to '{new_status}'. Valid next states: {valid_next}"
                )
            }

        proj = status_info.get("bmad_project", project or "")
        existing = self._read_vault_artifact(proj, name)
        if not existing:
            return {"error": f"Cannot read artifact file: {name}"}

        fm, body = existing
        fm["bmad_status"] = new_status
        history = fm.get("bmad_status_history", [])
        history.append({"status": new_status, "timestamp": _now_iso()})
        fm["bmad_status_history"] = history

        self._write_vault_artifact(proj, name, fm, body)
        return {"name": name, "previous_status": current_status, "new_status": new_status}

    # ── Linking ───────────────────────────────────────────────────────

    def link_artifacts(self, source: str, target: str, relationship: str, project: str | None = None) -> dict:
        """Create bidirectional link between two artifacts."""
        if relationship not in RELATIONSHIP_TYPES:
            return {"error": f"Invalid relationship: {relationship}. Valid: {RELATIONSHIP_TYPES}"}

        src_info = self.get_artifact_status(source, project)
        tgt_info = self.get_artifact_status(target, project)

        if not src_info.get("found"):
            return {"error": f"Source artifact not found: {source}"}
        if not tgt_info.get("found"):
            return {"error": f"Target artifact not found: {target}"}

        src_proj = src_info.get("bmad_project", "")
        tgt_proj = tgt_info.get("bmad_project", "")

        # Add link to source
        self._add_link(source, src_proj, target, relationship)
        # Add reverse link to target
        reverse_map = {
            "depends_on": "informs",
            "implements": "informs",
            "informs": "depends_on",
            "supersedes": "supersedes",
        }
        self._add_link(target, tgt_proj, source, reverse_map.get(relationship, relationship))

        return {"source": source, "target": target, "relationship": relationship, "bidirectional": True}

    def _add_link(self, artifact_name: str, project: str, target: str, relationship: str) -> None:
        existing = self._read_vault_artifact(project, artifact_name)
        if not existing:
            return
        fm, body = existing
        links = fm.get("bmad_linked_artifacts", [])

        # Don't duplicate
        for link in links:
            if link.get("target") == target and link.get("relationship") == relationship:
                return

        links.append({"target": target, "relationship": relationship})
        fm["bmad_linked_artifacts"] = links

        # Add wikilink in body if not present
        wikilink = f"[[{target}]]"
        if wikilink not in body:
            body = body.rstrip() + f"\n\nRelated: {wikilink}\n"

        self._write_vault_artifact(project, artifact_name, fm, body)

