        bmad = BmadBridge(config.vault_path, bmad_output)
        logger.info(f"BMAD bridge enabled: {bmad_output}")
    else:
        logger.info(f"BMAD bridge: output path not found ({bmad_output}), skipping")

if bmad:

    @mcp.tool()
    def bmad_sync_artifact(path: str) -> str:
        """Sync a BMAD artifact from _bmad-output/ to the vault with enriched frontmatter.

        Reads the source file, detects artifact type, applies the 3-tier
        frontmatter schema, validates, and writes the enriched copy to the vault.
        Source file is never modified. Operation is idempotent.

        Args:
            path: File path or glob pattern relative to _bmad-output/
        """
        if "*" in path or "?" in path:
            result = bmad.sync_glob(path)
        else:
            result = bmad.sync_artifact(path)
        return json.dumps(result, indent=2)

    @mcp.tool()
    def bmad_list_artifacts(
        artifact_type: str = "",
        status: str = "",
        project: str = "",
    ) -> str:
        """List tracked BMAD artifacts with optional filters.

        Args:
            artifact_type: Filter by type (prd, architecture, epic, story)
            status: Filter by lifecycle status (e.g. draft, approved)
            project: Filter by project name
        """
        results = bmad.list_artifacts(
            artifact_type=artifact_type or None,
            status=status or None,
            project=project or None,
        )
        if not results:
            return "No BMAD artifacts found."
        return json.dumps(results, indent=2)

    @mcp.tool()
    def bmad_get_artifact_status(name: str, project: str = "") -> str:
        """Get full detail for a single BMAD artifact.

        Returns lifecycle state, linked artifacts, frontmatter metadata,
        and status history.

        Args:
            name: Artifact name (filename without .md extension)
            project: Optional project name to narrow search
        """
        result = bmad.get_artifact_status(name, project=project or None)
        return json.dumps(result, indent=2)

    @mcp.tool()
    def bmad_update_status(name: str, new_status: str, project: str = "") -> str:
        """Update an artifact's lifecycle status with transition validation.

        Enforces valid lifecycle transitions per artifact type.
        Invalid transitions are rejected with a descriptive error.

        Args:
            name: Artifact name
            new_status: Target status (must be a valid transition)
            project: Optional project name
        """
        result = bmad.update_status(name, new_status, project=project or None)
        return json.dumps(result, indent=2)

    @mcp.tool()
    def bmad_link_artifacts(
        source: str, target: str, relationship: str, project: str = ""
    ) -> str:
        """Create a bidirectional link between two BMAD artifacts.

        Both source and target are updated. Supports relationship types:
        depends_on, implements, informs, supersedes.

        Args:
            source: Source artifact name
            target: Target artifact name
            relationship: Relationship type
            project: Optional project name
        """
        result = bmad.link_artifacts(
            source, target, relationship, project=project or None
        )
        return json.dumps(result, indent=2)

